export interface ParkPoint {
  lng: number
  lat: number
  /** Named parks are the real destinations; the rest are parkettes and greens. */
  named: boolean
}

let cache: ParkPoint[] | null = null

/** Unpacks once, on first use — the demo overlay is off by default. */
export function torontoParks(): ParkPoint[] {
  if (cache) return cache
  const out: ParkPoint[] = []
  for (let i = 0; i < PACKED.length; i += 3) {
    out.push({ lng: PACKED[i] / 1e5, lat: PACKED[i + 1] / 1e5, named: PACKED[i + 2] === 1 })
  }
  cache = out
  return out
}
